ALTER TABLE public.items ADD COLUMN pickup_style text NOT NULL DEFAULT '';
ALTER TABLE public.claims ADD COLUMN pickup_at timestamptz;
ALTER TABLE public.messages ADD COLUMN kind text NOT NULL DEFAULT 'text', ADD COLUMN slots timestamptz[] NOT NULL DEFAULT '{}', ADD COLUMN selected_at timestamptz, ADD COLUMN seen_at timestamptz;
ALTER TABLE public.kind_words ADD COLUMN photo_path text NOT NULL DEFAULT '';
ALTER TABLE public.notifications ADD COLUMN claim_id uuid REFERENCES public.claims(id), ADD COLUMN actor_id uuid REFERENCES public.profiles(id);
ALTER TABLE public.notifications DROP CONSTRAINT notifications_kind_check; ALTER TABLE public.notifications ADD CONSTRAINT notifications_kind_check CHECK(kind IN('match','renew','free_again','claimed','message','times','confirmed','picked_up','thanks'));
ALTER TABLE public.events DROP CONSTRAINT events_name_check; ALTER TABLE public.events ADD CONSTRAINT events_name_check CHECK(name IN('circle_link_opened','item_link_opened','signed_up','joined_circle','wish_added','item_posted','post_nudge_shown','item_shared','match_created','match_notification_sent','swipe_right','swipe_left','item_claimed','pickup_arranged','picked_up','thanked','claim_expired','item_expired','item_renewed','item_marked_donated','notify_me_tapped','clearout_interest_yes','clearout_interest_no','circle_created','circle_search_opened','circle_join_requested','circle_join_approved','circle_joined_from_search','circle_left','member_removed','profile_updated','custom_category_used','category_promoted','times_suggested','pickup_spot_shared'));
CREATE FUNCTION public.chat_participant(claim uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.claims c JOIN public.items i ON i.id=c.item_id WHERE c.id=claim AND public.has_item_access(i.id) AND auth.uid() IN(c.receiver_id,i.giver_id)) $$;
REVOKE ALL ON FUNCTION public.chat_participant(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.chat_participant(uuid) TO authenticated;
CREATE FUNCTION public.pickup_style_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.pickup_style=coalesce(nullif(current_setting('passalong.pickup_style',true),''),NEW.pickup_style); IF NEW.pickup_style NOT IN('','Porch pickup','Hand-off at my place','Meet up nearby','I can drop it off') THEN RAISE EXCEPTION 'Choose a pickup style'; END IF; RETURN NEW; END $$;
CREATE TRIGGER pickup_style_guard BEFORE INSERT OR UPDATE OF pickup_style ON public.items FOR EACH ROW EXECUTE FUNCTION public.pickup_style_guard();
CREATE FUNCTION public.chat_alert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.claims; i public.items; recipient uuid; actor uuid; label text; BEGIN
IF TG_TABLE_NAME='messages' THEN SELECT * INTO c FROM public.claims WHERE id=NEW.claim_id; SELECT * INTO i FROM public.items WHERE id=c.item_id; actor=NEW.sender_id; recipient=CASE WHEN actor=i.giver_id THEN c.receiver_id ELSE i.giver_id END; label=CASE WHEN NEW.kind='times' THEN 'times' ELSE 'message' END;
ELSE c=NEW; SELECT * INTO i FROM public.items WHERE id=c.item_id; actor=coalesce(auth.uid(),c.receiver_id); IF TG_OP='INSERT' THEN label='claimed'; recipient=i.giver_id; ELSIF NEW.status IS DISTINCT FROM OLD.status THEN label=CASE NEW.status WHEN 'pickup_arranged' THEN 'confirmed' WHEN 'picked_up' THEN 'picked_up' WHEN 'thanked' THEN 'thanks' ELSE NULL END; recipient=CASE WHEN actor=i.giver_id THEN c.receiver_id ELSE i.giver_id END; ELSE RETURN NEW; END IF; END IF;
IF label IS NOT NULL THEN INSERT INTO public.notifications(user_id,item_id,claim_id,actor_id,kind) VALUES(recipient,i.id,c.id,actor,label); END IF; RETURN NEW; END $$;
CREATE TRIGGER chat_message_alert AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.chat_alert(); CREATE TRIGGER chat_claim_alert AFTER INSERT OR UPDATE ON public.claims FOR EACH ROW EXECUTE FUNCTION public.chat_alert();
CREATE FUNCTION public.chat_doorbell() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; BEGIN IF TG_TABLE_NAME='notifications' THEN PERFORM realtime.send('{}'::jsonb,'changed','passalong:'||NEW.user_id::text,true); ELSE FOR uid IN SELECT c.receiver_id FROM public.claims c WHERE c.id=NEW.claim_id UNION SELECT i.giver_id FROM public.items i JOIN public.claims c ON c.item_id=i.id WHERE c.id=NEW.claim_id LOOP PERFORM realtime.send('{}'::jsonb,'changed','passalong:'||uid::text,true); END LOOP; END IF; RETURN NEW; END $$;
CREATE TRIGGER notification_doorbell AFTER INSERT OR UPDATE ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.chat_doorbell(); CREATE TRIGGER message_doorbell AFTER INSERT OR UPDATE ON public.messages FOR EACH ROW EXECUTE FUNCTION public.chat_doorbell();
CREATE POLICY passalong_private_doorbell ON realtime.messages FOR SELECT TO authenticated USING(realtime.topic()='passalong:'||auth.uid()::text);
CREATE POLICY participant_kind_words ON public.kind_words FOR SELECT TO authenticated USING(public.chat_participant(claim_id));
CREATE POLICY thanks_photo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='item-photos' AND EXISTS(SELECT 1 FROM public.kind_words k WHERE k.photo_path=objects.name AND (public.chat_participant(k.claim_id) OR k.show_on_profile AND EXISTS(SELECT 1 FROM public.circle_members a JOIN public.circle_members b ON a.circle_id=b.circle_id WHERE a.user_id=auth.uid() AND b.user_id=k.giver_id AND a.status='active' AND b.status='active'))));
DO $migration$ DECLARE body text; BEGIN SELECT pg_get_functiondef('public.passalong_action(text,jsonb)'::regprocedure) INTO body; body=replace(body,'public.passalong_action(','public.passalong_category_action('); EXECUTE body; END $migration$;
REVOKE ALL ON FUNCTION public.passalong_category_action(text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.passalong_category_action(text,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.passalong_action(action text,payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid=auth.uid(); c public.claims; i public.items; m public.messages; ts timestamptz[]; chosen timestamptz; result jsonb; event_name text; path text; BEGIN
IF u IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
IF action='post' THEN IF payload->>'pickup_style' NOT IN('Porch pickup','Hand-off at my place','Meet up nearby','I can drop it off') OR coalesce(payload->>'pickup_style','')='' THEN RAISE EXCEPTION 'Choose a pickup style'; END IF; PERFORM set_config('passalong.pickup_style',payload->>'pickup_style',true); END IF;
IF action IN('read_chat','suggest_times','confirm_time','share_spot','pickup','thank','arrange') THEN SELECT * INTO c FROM public.claims WHERE id=(payload->>'claim_id')::uuid FOR UPDATE; SELECT * INTO i FROM public.items WHERE id=c.item_id FOR UPDATE; IF NOT public.chat_participant(c.id) THEN RAISE EXCEPTION 'This conversation is private'; END IF;
IF action='read_chat' THEN UPDATE public.messages SET seen_at=now() WHERE claim_id=c.id AND sender_id<>u AND seen_at IS NULL; UPDATE public.notifications SET read_at=now() WHERE claim_id=c.id AND user_id=u AND read_at IS NULL; RETURN '{}'; END IF;
IF action IN('suggest_times','confirm_time','share_spot','arrange','pickup') AND (c.pickup_by<=now() OR c.status NOT IN('claimed','pickup_arranged')) THEN RAISE EXCEPTION 'This claim is not active'; END IF;
IF action='arrange' THEN RAISE EXCEPTION 'Ask the other person to confirm a suggested time';
ELSIF action='suggest_times' THEN ts=ARRAY(SELECT value::timestamptz FROM jsonb_array_elements_text(payload->'slots')); IF cardinality(ts) NOT BETWEEN 1 AND 3 OR EXISTS(SELECT 1 FROM unnest(ts) t WHERE t<=now()) OR cardinality(ts)<>(SELECT count(DISTINCT t) FROM unnest(ts) t) THEN RAISE EXCEPTION 'Pick up to 3 future times'; END IF; INSERT INTO public.messages(claim_id,sender_id,text,kind,slots) VALUES(c.id,u,'','times',ts); event_name='times_suggested';
ELSIF action='confirm_time' THEN SELECT * INTO m FROM public.messages WHERE id=(payload->>'message_id')::uuid AND claim_id=c.id FOR UPDATE; chosen=(payload->>'time')::timestamptz; IF m.id IS NULL OR m.kind<>'times' OR m.sender_id=u OR m.selected_at IS NOT NULL OR NOT chosen=ANY(m.slots) OR chosen<=now() THEN RAISE EXCEPTION 'Only the other person can confirm an offered future time'; END IF; UPDATE public.messages SET selected_at=chosen WHERE id=m.id; UPDATE public.claims SET status='pickup_arranged',pickup_at=chosen WHERE id=c.id; event_name='pickup_arranged';
ELSIF action='share_spot' THEN IF length(public.clean_text(payload->>'text')) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Enter a pickup spot up to 500 characters'; END IF; INSERT INTO public.messages(claim_id,sender_id,text,kind) VALUES(c.id,u,public.clean_text(payload->>'text'),'spot'); event_name='pickup_spot_shared';
ELSIF action='pickup' THEN IF c.status<>'pickup_arranged' THEN RAISE EXCEPTION 'Arrange pickup before marking it picked up'; END IF; RETURN public.passalong_category_action(action,payload);
ELSIF action='thank' THEN IF c.status<>'picked_up' OR c.receiver_id<>u THEN RAISE EXCEPTION 'Only the receiver can thank after pickup'; END IF; IF length(coalesce(public.clean_text(payload->>'text'),''))>200 THEN RAISE EXCEPTION 'Thank-you notes are limited to 200 characters'; END IF; path=coalesce(payload->>'photo_path',''); IF path<>'' AND NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='item-photos' AND name=path AND (storage.foldername(name))[1]=u::text) THEN RAISE EXCEPTION 'Upload your own photo first'; END IF; INSERT INTO public.kind_words(claim_id,writer_id,giver_id,text,show_on_profile,photo_path) VALUES(c.id,u,i.giver_id,coalesce(public.clean_text(payload->>'text'),''),coalesce((payload->>'show_on_profile')::boolean,false),path); RETURN public.passalong_category_action(action,payload);
END IF; INSERT INTO public.events(user_id,item_id,circle_id,name) VALUES(u,i.id,i.circle_id,event_name); RETURN jsonb_build_object('id',c.id); END IF;
RETURN public.passalong_category_action(action,payload); END $$;
CREATE FUNCTION public.chat_preferences(claim uuid) RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.pickup_times FROM public.profiles p JOIN public.items i ON i.giver_id=p.id JOIN public.claims c ON c.item_id=i.id WHERE c.id=claim AND public.chat_participant(c.id) $$; REVOKE ALL ON FUNCTION public.chat_preferences(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.chat_preferences(uuid) TO authenticated;